const novosLeads = $("Get a row3").all();
const leadsPlanilha = $("GetLeads1").all();

// Criamos um Set com todos os CNPJs que já existem na planilha
const cnpjsExistentes = new Set(
  leadsPlanilha
    .map(item => String(item.json.CNPJ || "").trim())
    .filter(cnpj => cnpj !== "")
);

// Filtramos apenas quem NÃO está no Set de existentes
return novosLeads.filter(item => {
  const cnpj = String(item.json.CNPJ || "").trim();
  return !cnpjsExistentes.has(cnpj);
});

const novosLeads = $("Get a row3").all();
