// Criamos um mapa para buscar o row_number pelo CNPJ
const mapaPlanilha = {};
leadsPlanilha.forEach(item => {
  const cnpj = String(item.json.CNPJ || "").trim();
  if (cnpj !== "") {
    mapaPlanilha[cnpj] = item.json.row_number;
  }
});

// Filtramos apenas quem existe e anexamos o row_number
return novosLeads
  .filter(item => {
    const cnpj = String(item.json.CNPJ || "").trim();
    return cnpj !== "" && mapaPlanilha[cnpj] !== undefined;
  })
  .map(item => {
    const cnpj = String(item.json.CNPJ).trim();
    return {
      json: {
        ...item.json,
        row_number: mapaPlanilha[cnpj]
      }
    };
  });

