  const raw = String(item.json.Telefone ?? "").trim();
  if (!raw) return [{ json: { ...item.json, telefoneProcessado: "" } }];

  // Só dígitos
  let digits = raw.replace(/\D/g, "");

  // Se vier com 00 internacional (ex: 0055...), remove 00
  if (digits.startsWith("00")) digits = digits.slice(2);

  // Helpers
  const uniq = (arr) => [...new Set(arr)].filter((v) => v && String(v).length > 0);

  const variants = [];

  // Detecta se tem 55
  const has55 = digits.startsWith("55");

  // Função que gera combinações de prefixo (+ / sem +) e (55 / sem 55)
  function addPrefixCombos(fullNoPlus) {
    // fullNoPlus é "55..." ou "DDD..." ou "NUM..."
    const noPlus = String(fullNoPlus);

    // com/sem +
    variants.push(noPlus);
    variants.push("+" + noPlus);

    // se começar com 55, também gera sem 55
    if (noPlus.startsWith("55")) {
      const no55 = noPlus.slice(2);
      variants.push(no55);
      variants.push("+" + no55);
    }

    // se não começar com 55, também gera com 55 (quando fizer sentido)
    // (só tenta se parecer BR: tamanho 10/11 (DDD+num) ou 8/9 (num))
    const d = noPlus.replace(/\D/g, "");
    if (!d.startsWith("55")) {
      if (d.length === 10 || d.length === 11 || d.length === 8 || d.length === 9) {
        variants.push("55" + d);
        variants.push("+55" + d);
      }
    }
  }

  // Função que gera com/sem DDD, com/sem 9 (quando aplicável)
  function addDddAnd9Combos(pais, ddd, num) {
    const base = `${pais}${ddd}${num}`;
    addPrefixCombos(base);

    // variações sem DDD
    addPrefixCombos(num);

    // variações só com DDD+num (sem 55)
    addPrefixCombos(`${ddd}${num}`);

    // Agora tenta variações com/sem 9 quando num for 8/9 dígitos (BR)
    // Regra prática:
    // - Celular local: 9 dígitos (começa com 9)
    // - Fixo local: 8 dígitos (não começa com 9 normalmente)
    // Se vier 8 dígitos, gera versão com 9 + num
    // Se vier 9 dígitos começando com 9, gera sem o 9 (8 dígitos)
    const onlyNum = String(num);

    const numCom9 = onlyNum.length === 9
      ? onlyNum
      : ("9" + onlyNum);

    const numSem9 = (onlyNum.length === 9 && onlyNum.startsWith("9"))
      ? onlyNum.slice(1)
      : (onlyNum.length === 8 ? onlyNum : onlyNum); // se já não dá pra tirar, mantém

    // Só aplica quando fizer sentido (8 ou 9 dígitos)
    if (onlyNum.length === 8 || (onlyNum.length === 9 && onlyNum.startsWith("9"))) {
      // com 9
      addPrefixCombos(`${pais}${ddd}${numCom9}`);
      addPrefixCombos(`${ddd}${numCom9}`);
      addPrefixCombos(`${numCom9}`);

      // sem 9
      addPrefixCombos(`${pais}${ddd}${numSem9}`);
      addPrefixCombos(`${ddd}${numSem9}`);
      addPrefixCombos(`${numSem9}`);
    }
  }

  // --- Tentativa de interpretar como BR ---
  // Casos comuns:
  // - 55 + DDD(2) + num(8/9)  => 12/13 dígitos
  // - DDD(2) + num(8/9)       => 10/11 dígitos
  // - num(8/9)                => 8/9 dígitos

  // Se tiver 55, remove pra analisar tamanho
  const digitsNo55 = has55 ? digits.slice(2) : digits;

  // 55 + DDD + NUM
  if (has55 && (digits.length === 12 || digits.length === 13)) {
    const pais = "55";
    const ddd = digits.slice(2, 4);
    const num = digits.slice(4);
    addDddAnd9Combos(pais, ddd, num);

  // DDD + NUM (sem 55)
  } else if (!has55 && (digits.length === 10 || digits.length === 11)) {
    const pais = "55";
    const ddd = digits.slice(0, 2);
    const num = digits.slice(2);
    addDddAnd9Combos(pais, ddd, num);

  // Só NUM (sem DDD)
  } else if (digits.length === 8 || digits.length === 9) {
    // Não dá pra cravar DDD. Gera com/sem +, com/sem 55, e com/sem 9 se aplicável.
    addPrefixCombos(digits);

    if (digits.length === 8) {
      addPrefixCombos("9" + digits); // com 9
    } else if (digits.length === 9 && digits.startsWith("9")) {
      addPrefixCombos(digits.slice(1)); // sem 9
    }

  // Qualquer outro formato: devolve o que der
  } else {
    // Ainda assim gera com/sem +
    variants.push(digits);
    variants.push("+" + digits);

    // e se não tiver 55 mas parecer que pode ser BR (ex: 12/13 com 55 faltando)
    // (aqui não invento muito — só adiciono 55 na frente)
    if (!digits.startsWith("55")) {
      variants.push("55" + digits);
      variants.push("+55" + digits);
    }
  }

  const uniqueVariations = uniq(variants);

  return uniqueVariations.map((tel) => ({
    json: { ...item.json, telefoneProcessado: tel },
  }));
});

